INSERT INTO TB_TRATAMENTO (ID_CASO, ID_TIPO_TRATAMENTO, ID_UNIDADE_TRATAMENTO, DATA_INICIO_TRATAMENTO, DIAS_ESPERA, ID_STATUS_PRAZO)
  SELECT p.ID_CASO, tt.ID_TIPO_TRATAMENTO, ut.ID_UNIDADE, TO_DATE('25/01/2023','DD/MM/YYYY'), 77, sp.ID_STATUS_PRAZO
  FROM TB_CASO_PACIENTE p, TB_TIPO_TRATAMENTO tt, TB_STATUS_PRAZO sp, TB_UNIDADE_SAUDE ut
  WHERE p.COD_CASO = 'CASO-0001' AND tt.NOME_TIPO_TRATAMENTO = 'Quimioterapia' AND sp.COD_STATUS = 'Vencido' AND ut.COD_CNES = '2090236';
